// Normalize all job data into a unified schema
const SEARCH_KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant'
];

const jobs = [];
const today = new Date().toISOString().split('T')[0];

for (const item of $input.all()) {
  const raw = item.json;
  let normalized = null;

  // Remote OK
  if (Array.isArray(raw) && raw[0] && raw[0].legal) {
    for (const job of raw.slice(1)) {
      if (!job || !job.position) continue;
      normalized = {
        job_id: `remoteok_${job.id || job.slug}`,
        job_title: job.position || '',
        company: job.company || '',
        job_url: job.url || `https://remoteok.com/remote-jobs/${job.slug}`,
        source: 'Remote OK',
        location_text: job.location || 'Worldwide',
        salary: job.salary || '',
        description: (job.description || '') + ' ' + (job.tags ? job.tags.join(' ') : ''),
        posted_date: job.date || today,
        tags: Array.isArray(job.tags) ? job.tags.join(',') : '',
        date_found: today
      };
      jobs.push(normalized);
    }
    continue;
  }

  // Remotive
  if (raw.jobs && Array.isArray(raw.jobs)) {
    for (const job of raw.jobs) {
      normalized = {
        job_id: `remotive_${job.id}`,
        job_title: job.title || '',
        company: job.company_name || '',
        job_url: job.url || '',
        source: 'Remotive',
        location_text: job.candidate_required_location || 'Worldwide',
        salary: job.salary || '',
        description: (job.description || '') + ' ' + (job.tags ? job.tags.join(' ') : ''),
        posted_date: job.publication_date || today,
        tags: Array.isArray(job.tags) ? job.tags.join(',') : '',
        date_found: today
      };
      jobs.push(normalized);
    }
    continue;
  }

  // Himalayas
  if (raw.data && Array.isArray(raw.data)) {
    for (const job of raw.data) {
      normalized = {
        job_id: `himalayas_${job.id || job.slug}`,
        job_title: job.title || '',
        company: job.companyName || job.company?.name || '',
        job_url: job.applicationUrl || `https://himalayas.app/jobs/${job.slug}`,
        source: 'Himalayas',
        location_text: job.locationRestrictions?.join(', ') || 'Worldwide',
        salary: job.salaryRange || '',
        description: job.description || '',
        posted_date: job.publishedAt || today,
        tags: Array.isArray(job.tags) ? job.tags.join(',') : '',
        date_found: today
      };
      jobs.push(normalized);
    }
    continue;
  }

  // RSS feeds (WWR, Dynamite Jobs)
  if (raw.title && raw.link) {
    const source = raw.link && raw.link.includes('weworkremotely') ? 'We Work Remotely' : 'Dynamite Jobs';
    normalized = {
      job_id: `${source.toLowerCase().replace(/\s/g,'_')}_${Buffer.from(raw.link).toString('base64').slice(0,16)}`,
      job_title: raw.title || '',
      company: raw.creator || raw.author || raw['dc:creator'] || '',
      job_url: raw.link || '',
      source: source,
      location_text: raw.category || 'Worldwide',
      salary: '',
      description: raw.content || raw.contentSnippet || raw.summary || raw.title || '',
      posted_date: raw.pubDate || raw.isoDate || today,
      tags: '',
      date_found: today
    };
    jobs.push(normalized);
    continue;
  }

  // HTML scrape fallback (YC, Wellfound, Otta) - parse what we can
  if (typeof raw === 'string' || raw.data) {
    const html = typeof raw === 'string' ? raw : (raw.data || '');
    // Basic extraction from JSON-LD or meta tags if present
    const jsonLdMatches = html.match(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi) || [];
    for (const match of jsonLdMatches) {
      try {
        const content = match.replace(/<script[^>]*>/i, '').replace(/<\/script>/i, '');
        const data = JSON.parse(content);
        const jobList = Array.isArray(data) ? data : [data];
        for (const j of jobList) {
          if (j['@type'] === 'JobPosting') {
            normalized = {
              job_id: `scraped_${Buffer.from(j.url || j.title || '').toString('base64').slice(0,16)}`,
              job_title: j.title || '',
              company: j.hiringOrganization?.name || '',
              job_url: j.url || '',
              source: 'Scraped',
              location_text: j.jobLocation?.address?.addressCountry || 'Unknown',
              salary: j.baseSalary?.value?.value || '',
              description: j.description || '',
              posted_date: j.datePosted || today,
              tags: '',
              date_found: today
            };
            jobs.push(normalized);
          }
        }
      } catch (e) { /* skip malformed JSON-LD */ }
    }
    continue;
  }
}

// Keyword relevance pre-filter - keep if any keyword matches title or description
const filtered = jobs.filter(job => {
  const text = (job.job_title + ' ' + job.description + ' ' + job.tags).toLowerCase();
  return SEARCH_KEYWORDS.some(kw => text.includes(kw.toLowerCase()));
});

return filtered.map(j => ({ json: j }));

// Deduplicate against existing Google Sheets data
const incoming = $('Normalize Job Data').all();
const existing = $('Read Existing Jobs from Sheet').all();

// Build lookup sets from existing data
const existingUrls = new Set(existing.map(e => e.json.job_url).filter(Boolean));
const existingCompanyTitle = new Set(
  existing.map(e => `${(e.json.company || '').toLowerCase()}|${(e.json.job_title || '').toLowerCase()}`).filter(Boolean)
);

const unique = incoming.filter(item => {
  const url = item.json.job_url;
  const key = `${(item.json.company || '').toLowerCase()}|${(item.json.job_title || '').toLowerCase()}`;
  return !existingUrls.has(url) && !existingCompanyTitle.has(key);
});

return unique;

// Taiwan eligibility hard filter using keyword matching
const REJECT_PATTERNS = [
  /\bus only\b/i, /\bus-only\b/i,
  /\bcanada only\b/i, /\bcanada-only\b/i,
  /\buk only\b/i, /\buk-only\b/i,
  /\beu only\b/i, /\beu-only\b/i,
  /\beurope only\b/i, /\beurope-only\b/i,
  /\baustralia only\b/i, /\baustralia-only\b/i,
  /\bmust be based in\b/i,
  /\bmust live in\b/i,
  /\bmust be authorized to work in\b/i,
  /\blocal work permit required\b/i,
  /\bhybrid\b/i,
  /\bonsite\b/i, /\bon-site\b/i, /\bon site\b/i,
  /\boffice required\b/i,
  /\bremote within [a-z]+ only\b/i,
  /\bfixed us hours\b/i,
  /\bfixed eu hours\b/i,
  /\brelocate\b/i,
  /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i
];

const KEEP_SIGNALS = [
  /worldwide remote/i, /global remote/i, /work from anywhere/i,
  /anywhere/i, /apac remote/i, /apac/i,
  /international contractors?/i, /contractor role/i, /b2b contractor/i,
  /hires via deel/i, /hires via remote\.com/i, /hires via oyster/i,
  /eor supported/i, /employer of record/i,
  /remote.?first/i, /distributed team/i, /fully remote/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const text = `${item.json.job_title} ${item.json.description} ${item.json.location_text} ${item.json.tags}`.toLowerCase();

  let rejectReason = null;
  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(text)) {
      rejectReason = pattern.toString();
      break;
    }
  }

  if (rejectReason) {
    item.json._hard_filter_reject = rejectReason;
    rejected.push(item);
  } else {
    const hasKeepSignal = KEEP_SIGNALS.some(p => p.test(text));
    item.json._has_keep_signal = hasKeepSignal;
    passed.push(item);
  }
}

// Store rejected count for digest
const summary = {
  us_only: rejected.filter(r => /us only|us-only/i.test(r.json._hard_filter_reject || '')).length,
  eu_only: rejected.filter(r => /eu only|europe only/i.test(r.json._hard_filter_reject || '')).length,
  hybrid: rejected.filter(r => /hybrid|onsite|on-site/i.test(r.json._hard_filter_reject || '')).length,
  canada_uk_aus: rejected.filter(r => /canada|uk only|australia/i.test(r.json._hard_filter_reject || '')).length
};

// Pass the rejection summary through on every passed item
return [
  ...passed.map(item => { item.json._reject_summary = summary; return item; }),
  ...rejected.map(item => { item.json._reject_summary = summary; item.json._is_rejected = true; return item; })
];

// Parse AI response and merge with job data
const job = $('Process Jobs One by One').item.json;
const aiRaw = $input.item.json.content || $input.item.json.text || $input.item.json.message || '';

let aiResult = {
  taiwan_eligible: 'unclear',
  reason: 'AI parse error',
  location_risk: 'high',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  const jsonMatch = aiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = JSON.parse(jsonMatch[0]);
  }
} catch (e) { /* use defaults */ }

return [{ json: { ...job, ...aiResult } }];

// Route based on AI decision
const item = $input.item.json;

if (item.decision === 'reject' || item.taiwan_eligible === 'no') {
  item._ai_rejected = true;
} else {
  item._ai_rejected = false;
}

return [{ json: item }];

// Async work culture filter
const item = $input.item.json;
const text = `${item.job_title} ${item.description} ${item.tags}`.toLowerCase();

const ASYNC_SIGNALS = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'remote-first', 'low meeting culture',
  'work across time zones', 'no meeting', 'own schedule', 'own hours'
];

const SYNC_BLOCKERS = [
  'strict 9 to 5', 'strict 9-to-5', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required',
  'must overlap full business day', 'mandatory meetings', 'daily standup required'
];

const syncBlocked = SYNC_BLOCKERS.some(s => text.includes(s));
if (syncBlocked) {
  item._async_rejected = true;
  item.async_level = 'sync_only';
  return [{ json: item }];
}

const asyncMatches = ASYNC_SIGNALS.filter(s => text.includes(s));
let asyncLevel = 'unknown';
if (asyncMatches.some(s => ['async', 'asynchronous', 'no meeting', 'own schedule'].includes(s))) {
  asyncLevel = 'high';
} else if (asyncMatches.some(s => ['flexible hours', 'flexible schedule', 'distributed team'].includes(s))) {
  asyncLevel = 'medium';
} else if (asyncMatches.some(s => ['remote first', 'remote-first', 'work across time zones'].includes(s))) {
  asyncLevel = 'medium';
} else {
  asyncLevel = 'low';
}

item.async_level = asyncLevel;
item._async_rejected = false;
return [{ json: item }];

// Role fit categorization
const item = $input.item.json;
const titleLower = (item.job_title || '').toLowerCase();
const textLower = `${item.job_title} ${item.description}`.toLowerCase();

const TIER1_ROLES = [
  'data analyst', 'data scientist', 'junior data scientist',
  'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst',
  'ai marketing', 'ai automation', 'ai workflow',
  'creative strategist', 'martech', 'marketing technology'
];

const TIER2_ROLES = [
  'analyst', 'scientist', 'marketing', 'data', 'analytics',
  'reporting', 'insights', 'automation', 'growth', 'digital marketing'
];

let roleCategory = 'other';
let roleFitScore = 0;

if (TIER1_ROLES.some(r => titleLower.includes(r))) {
  roleCategory = 'core_fit';
  roleFitScore = 25;
} else if (TIER1_ROLES.some(r => textLower.includes(r))) {
  roleCategory = 'core_fit_desc';
  roleFitScore = 20;
} else if (TIER2_ROLES.some(r => titleLower.includes(r))) {
  roleCategory = 'adjacent';
  roleFitScore = 15;
} else if (TIER2_ROLES.some(r => textLower.includes(r))) {
  roleCategory = 'adjacent_desc';
  roleFitScore = 10;
}

item.role_category = roleCategory;
item._role_fit_score = roleFitScore;

// Skip roles with zero fit
if (roleFitScore === 0) {
  item._role_rejected = true;
} else {
  item._role_rejected = false;
}

return [{ json: item }];

// Score each job 0-100
const item = $input.item.json;
const text = `${item.job_title} ${item.description} ${item.location_text} ${item.tags}`.toLowerCase();
let score = 0;
const reasons = [];

// --- Taiwan Eligibility (40 pts max) ---
if (
  item.taiwan_eligible === 'yes' ||
  /worldwide remote|global remote|work from anywhere|anywhere|contractor/i.test(text)
) {
  score += 40;
  reasons.push('worldwide/contractor friendly (+40)');
} else if (/apac|asia.?pacific/i.test(text)) {
  score += 30;
  reasons.push('APAC friendly (+30)');
} else if (item.taiwan_eligible === 'unclear' && item.location_risk !== 'high') {
  score += 20;
  reasons.push('no explicit country restriction (+20)');
} else {
  // country restricted
  reasons.push('country restricted (+0)');
}

// --- Async Fit (25 pts max) ---
const asyncLevel = item.async_level || 'unknown';
if (asyncLevel === 'high') {
  score += 25;
  reasons.push('clearly async (+25)');
} else if (asyncLevel === 'medium' && /flexible hours|flexible schedule/i.test(text)) {
  score += 20;
  reasons.push('flexible hours (+20)');
} else if (asyncLevel === 'medium') {
  score += 15;
  reasons.push('distributed team (+15)');
} else if (/remote.?first|remote first/i.test(text)) {
  score += 10;
  reasons.push('remote-first (+10)');
}

// --- Role Fit (25 pts max) ---
score += item._role_fit_score || 0;
if (item._role_fit_score > 0) reasons.push(`role fit: ${item.role_category} (+${item._role_fit_score})`);

// --- Salary Fit (25 pts max) ---
const salaryText = (item.salary || '').toLowerCase();
const salaryNumbers = (item.salary || '').match(/[\d,]+/g) || [];
const maxSalary = Math.max(...salaryNumbers.map(n => parseInt(n.replace(/,/g,''),10)).filter(Boolean));

if (maxSalary >= 5000 || /\$5[,.]?000|5k|60,000|70,000|80,000|90,000|100,000/.test(salaryText)) {
  score += 25;
  reasons.push('salary >$5k/mo (+25)');
} else if (maxSalary >= 3000 || /\$3[,.]?000|3k|36,000|40,000/.test(salaryText)) {
  score += 15;
  reasons.push('salary >$3k/mo (+15)');
} else if (item.salary && item.salary.trim() !== '') {
  score += 10;
  reasons.push('salary listed (+10)');
}

// Apply rejections
if (item._async_rejected) { score = Math.min(score, 40); reasons.push('sync schedule penalized'); }
if (item._role_rejected) { score = Math.min(score, 30); }

item.score = score;
item.why_good_fit = reasons.join('; ');

// Final decision
if (item.taiwan_eligible === 'no' || item.location_risk === 'high' || item.timezone_risk === 'high' || score < 70) {
  item.decision = 'reject';
} else if (item.taiwan_eligible === 'unclear' && score >= 85 && item.location_risk === 'medium') {
  item.decision = 'manual_check';
} else if (item.taiwan_eligible === 'yes' && score >= 85 && ['low','medium'].includes(item.timezone_risk) && ['high','medium'].includes(item.async_level)) {
  item.decision = 'apply_immediately';
} else if (score >= 70) {
  item.decision = 'keep';
} else {
  item.decision = 'reject';
}

return [{ json: item }];

// Build daily digest
const jobs = $input.item.json.all_jobs || [];
const today = new Date().toISOString().split('T')[0];

// Sort by score descending
const sorted = [...jobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const topJobs = sorted.filter(j => j.score >= 70).slice(0, 10);
const manualCheck = sorted.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

// Count rejections from the reject summary (pass through first item)
const rejectSummary = jobs[0]?._reject_summary || {};

let html = `<h1>Daily Taiwan Eligible Async Remote Jobs — ${today}</h1>`;
html += `<p><strong>Found today:</strong> ${topJobs.length} eligible jobs</p>`;

html += '<h2>Top Jobs</h2>';
topJobs.forEach((job, i) => {
  html += `
  <div style="border:1px solid #ccc; padding:12px; margin:8px 0; border-radius:6px;">
    <h3>${i + 1}. ${job.job_title}</h3>
    <p><strong>Company:</strong> ${job.company}</p>
    <p><strong>Score:</strong> ${job.score}/100</p>
    <p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible}</p>
    <p><strong>Reason:</strong> ${job.reason || 'N/A'}</p>
    <p><strong>Async Level:</strong> ${job.async_level}</p>
    <p><strong>Timezone Risk:</strong> ${job.timezone_risk}</p>
    <p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>
    <p><strong>Why it fits Jerry:</strong> ${job.why_good_fit}</p>
    <p><a href="${job.job_url}">Apply →</a></p>
  </div>`;
});

if (manualCheck.length > 0) {
  html += '<h2>Manual Check Required</h2>';
  manualCheck.slice(0,5).forEach(job => {
    html += `<p>• <a href="${job.job_url}">${job.job_title}</a> at ${job.company} (Score: ${job.score}, Risk: ${job.location_risk})</p>`;
  });
}

html += '<h2>Rejected Summary</h2>';
html += `<ul>
  <li>US only: ${rejectSummary.us_only || 0}</li>
  <li>EU/Europe only: ${rejectSummary.eu_only || 0}</li>
  <li>Hybrid/Onsite: ${rejectSummary.hybrid || 0}</li>
  <li>Canada/UK/Australia: ${rejectSummary.canada_uk_aus || 0}</li>
</ul>`;

return [{ json: { digest_html: html, job_count: topJobs.length, today } }];
